  CREATE FUNCTION dbo.AKMOGUDI_KOL_ANBAR  (@Forms___F_MENU_ANBAR___DT2 BIGINT,  @Forms___F_MENU_ANBAR___MANBAR nvarchar(10))  RETURNS Table  AS  RETURN ( SELECT     AKMOGO_AVL_KOL.CODE, ROUND(ISNULL(ISNULL(AKMOGO_AVL_KOL.SMEGH, 0) - ISNULL(AK_MOGO_FR.MEG, 0), 0), 2) AS MAND, ISNULL(AK_MOGO_FR.MEG, 0) AS MEGF, AKMOGO_AVL_KOL.SMEGH, dbo.lastavrage(dbo.STUF_FSK.CODE, dbo.STUF_FSK.ANBAR, @Forms___F_MENU_ANBAR___DT2) AS FII, ISNULL(dbo.lastavrage(dbo.STUF_FSK.CODE, dbo.STUF_FSK.ANBAR,  @Forms___F_MENU_ANBAR___DT2) * (ISNULL(AKMOGO_AVL_KOL.SMEGH, 0) - ISNULL(AK_MOGO_FR.MEG, 0)), 0) AS MABLK, dbo.STUF_DEF.NAME, dbo.TCOD_VAHEDS.NAMES, ' ' AS KK, AKMOGO_AVL_KOL.ANBAR, dbo.TCOD_ANBAR.NAMES AS ANBARN,    CAST(AKMOGO_AVL_KOL.CODE AS BIGINT) AS VCOD, dbo.GHEYMAT_TAMAM.GHEMAT, dbo.TCOD_STUFGROUP.CODE AS GRCOD,  dbo.TCOD_STUFGROUP.NAMES AS GRNAME, dbo.STUF_DEF.N_FANI, dbo.STUF_DEF.TOZIH, ISNULL(dbo.FNESBAT.FNESBAT, 1) AS NESBAT, ROUND(ISNULL(ISNULL(AKMOGO_AVL_KOL.SMEGH, 0) - ISNULL(AK_MOGO_FR.MEG, 0), 0) / ISNULL(dbo.FNESBAT.FNESBAT, 1), 0) AS MANDF, ISNULL(AK_BARGIRI_NASHODAH.MEGBARG, 0) AS MEGHBAR, ISNULL(AK_RESERVED.MEGHRES, 0) AS MEGHRES, ISNULL(NULLIF(dbo.STUF_FSK.B_SEF, 0), dbo.STUF_DEF.B_SEF) AS B_SEF, dbo.STUF_DEF.MABL_F , ROUND(ISNULL(ISNULL(AKMOGO_AVL_KOL.SMEGH, 0) - ISNULL(AK_MOGO_FR.meg, 0), 0), 2) - ISNULL(NULLIF(dbo.STUF_FSK.B_SEF, 0), dbo.STUF_DEF.B_SEF) AS bsef, ROUND(ISNULL(ISNULL(AKMOGO_AVL_KOL.SMEGH, 0) - ISNULL(AK_MOGO_FR.MEG, 0), 0), 2) - ISNULL(NULLIF(dbo.STUF_FSK.N_SEF, 0), dbo.STUF_DEF.N_SEF) AS nsef, ROUND(ISNULL(ISNULL(AKMOGO_AVL_KOL.SMEGH, 0) - ISNULL(AK_MOGO_FR.MEG, 0), 0), 2) - ISNULL(NULLIF(dbo.STUF_FSK.MIN_M, 0), dbo.STUF_DEF.MIN_M) AS minm, ROUND(ISNULL(ISNULL(AKMOGO_AVL_KOL.SMEGH, 0) - ISNULL(AK_MOGO_FR.MEG, 0), 0), 2) - ISNULL(NULLIF(dbo.STUF_FSK.MAX_M, 0), dbo.STUF_DEF.MAX_M) AS maxm, ISNULL(NULLIF(dbo.STUF_FSK.MAX_M, 0), dbo.STUF_DEF.MAX_M) AS MAX_M, dbo.STUF_DEF.VAZN, ROUND(ISNULL(ISNULL(AKMOGO_AVL_KOL.SMEGH, 0)  - ISNULL(AK_MOGO_FR.MEG, 0), 0), 2) * dbo.STUF_DEF.VAZN AS VAZNK, dbo.TCODE_MENUITEM.NAMES AS menuit, ROUND(ISNULL(ISNULL(AKMOGO_AVL_KOL.SMEGH, 0) - ISNULL(AK_MOGO_FR.MEG, 0), 0), 2) + ISNULL(AK_BARGIRI_NASHODAH.MEGBARG, 0) + ISNULL(AK_RESERVED.MEGHRES, 0)   AS fisiclymand, dbo.STUF_FSK.POSITION FROM         dbo.TCOD_VAHEDS INNER JOIN  dbo.TCOD_ANBAR INNER JOIN   dbo.STUF_DEF LEFT OUTER JOIN  dbo.GHEYMAT_TAMAM ON dbo.STUF_DEF.CODE = dbo.GHEYMAT_TAMAM.CODE INNER JOIN  dbo.STUF_FSK LEFT OUTER JOIN   dbo.AKMOGO_AVL_KOL(@Forms___F_MENU_ANBAR___DT2, @Forms___F_MENU_ANBAR___MANBAR) AS AKMOGO_AVL_KOL ON   dbo.STUF_FSK.ANBAR = AKMOGO_AVL_KOL.ANBAR AND dbo.STUF_FSK.CODE = AKMOGO_AVL_KOL.CODE LEFT OUTER JOIN    dbo.AK_MOGO_FR(@Forms___F_MENU_ANBAR___DT2, @Forms___F_MENU_ANBAR___MANBAR) AS AK_MOGO_FR ON    dbo.STUF_FSK.ANBAR = AK_MOGO_FR.ANBAR AND dbo.STUF_FSK.CODE = AK_MOGO_FR.CODE ON dbo.STUF_DEF.CODE = dbo.STUF_FSK.CODE ON   dbo.TCOD_ANBAR.CODE = dbo.STUF_FSK.ANBAR ON dbo.TCOD_VAHEDS.CODE = dbo.STUF_DEF.VAHED LEFT OUTER JOIN  dbo.AK_RESERVED(@Forms___F_MENU_ANBAR___DT2, @Forms___F_MENU_ANBAR___MANBAR) AS AK_RESERVED ON   dbo.STUF_FSK.CODE = AK_RESERVED.CODE AND dbo.STUF_FSK.ANBAR = AK_RESERVED.ANBAR LEFT OUTER JOIN   dbo.TCODE_MENUITEM ON dbo.STUF_DEF.MENUIT = dbo.TCODE_MENUITEM.CODE LEFT OUTER JOIN    dbo.AK_BARGIRI_NASHODAH(@Forms___F_MENU_ANBAR___DT2, @Forms___F_MENU_ANBAR___MANBAR) AS AK_BARGIRI_NASHODAH ON   dbo.STUF_FSK.CODE = AK_BARGIRI_NASHODAH.CODE AND dbo.STUF_FSK.ANBAR = AK_BARGIRI_NASHODAH.ANBAR LEFT OUTER JOIN dbo.FNESBAT ON dbo.STUF_DEF.CODE = dbo.FNESBAT.CODE RIGHT OUTER JOIN   dbo.TCOD_STUFGROUP ON dbo.STUF_DEF.RADAH = dbo.TCOD_STUFGROUP.CODE  WHERE     (NOT (AKMOGO_AVL_KOL.CODE IS NULL)))
